import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Baseline Memory (ML Tab)","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/baseline-ml.md","filePath":"openshield-xdp/user-guide/baseline-ml.md","lastUpdated":1785966053000}'),n={name:"openshield-xdp/user-guide/baseline-ml.md"};function o(l,e,r,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="baseline-memory-ml-tab" tabindex="-1">Baseline Memory (ML Tab) <a class="header-anchor" href="#baseline-memory-ml-tab" aria-label="Permalink to &quot;Baseline Memory (ML Tab)&quot;">​</a></h1><p>Since v2.4.0, OpenShield doesn&#39;t just learn your traffic — it <em>remembers</em> it. The dynamic baseline (the &quot;what does normal look like&quot; reference every detection is measured against) now has a 30-day memory with operator controls, visible in the TUI&#39;s <strong>ML tab</strong> (press <code>m</code>).</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li>The live baseline is a fast-adapting EMA of your inbound traffic (PPS, BPS, TCP, UDP, ICMP, SYN) — updated every few seconds, frozen during attacks.</li><li><strong>Every day at local midnight</strong>, the learned baseline is snapshotted to disk. Up to <strong>30 daily snapshots</strong> are kept; the oldest rolls off.</li><li>The baseline the detector actually uses is a <strong>recency-weighted merge</strong>: the live EMA gets ~15% of the vote, the 30 days of history ~85% (recent days weigh more — 0.85 decay per day of age).</li></ul><p>The practical effect: one weird day — an attack that slipped under detection, a one-off event, a migration — can only drag your detection so far. The other 29 days outvote it.</p><h2 id="when-an-attack-bypasses-detection" tabindex="-1">When an attack bypasses detection <a class="header-anchor" href="#when-an-attack-bypasses-detection" aria-label="Permalink to &quot;When an attack bypasses detection&quot;">​</a></h2><p>If an attack was slow enough to stay under the trigger, the ceiling guard stops it from <em>fully</em> poisoning the baseline — but it can still tilt that day&#39;s learning. Fix it in two keystrokes:</p><ol><li>Open the TUI → <code>m</code> (ML tab).</li><li>Find the poisoned day in the 30-day history, press <code>d</code> (confirm) — the snapshot is deleted and the merged baseline <strong>reconfigures immediately</strong>.</li></ol><p>If the bypass happened <strong>today</strong> (not yet snapshotted), press <code>D</code> — this resets the <em>live</em> baseline from the remaining history. Same effect, same immediacy.</p><p>CLI equivalent:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # live + merged values, thresholds, history</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2026-08-04</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # remove a day, recompute</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># reset today&#39;s live baseline</span></span></code></pre></div><h2 id="import-export" tabindex="-1">Import / export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import / export&quot;">​</a></h2><p>Move a trained baseline between servers (e.g. a replacement node, or after reinstall):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # live baseline + all 30 days</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baseline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # replace + reconfigure instantly</span></span></code></pre></div><p>In the TUI: <code>e</code> exports to <code>/var/lib/openshield/state/baseline-export-&lt;timestamp&gt;.json</code>; <code>i</code> prompts for a path and imports.</p><p>Importing also <strong>seeds cold starts</strong>: a fresh install with imported (or retained) history converges to sane detection in seconds instead of learning for hours.</p><h2 id="what-the-ml-tab-shows" tabindex="-1">What the ML tab shows <a class="header-anchor" href="#what-the-ml-tab-shows" aria-label="Permalink to &quot;What the ML tab shows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Panel</th><th>Contents</th></tr></thead><tbody><tr><td><strong>Learning</strong></td><td><code>active</code> / <code>frozen (attack active)</code> / <code>suppressed (schedule)</code>, merge weights, spike thresholds and the configured floors</td></tr><tr><td><strong>Baseline</strong></td><td>live vs merged side by side — PPS, BPS, TCP, UDP, ICMP, SYN</td></tr><tr><td><strong>30-Day History</strong></td><td>every snapshot with date + rates; cursor selects a day for deletion</td></tr></tbody></table><p>The tab auto-refreshes every 5 seconds. Keys: <code>j/k</code> scroll, <code>PgUp/PgDn</code> page, <code>d</code> delete day, <code>D</code> reset today, <code>e</code> export, <code>i</code> import, <code>r</code> refresh.</p><h2 id="related-knobs" tabindex="-1">Related knobs <a class="header-anchor" href="#related-knobs" aria-label="Permalink to &quot;Related knobs&quot;">​</a></h2><ul><li><code>dynamic.spike_percentage</code> — how far above the merged baseline = attack (default 200 → 3×).</li><li><code>dynamic.attack_min_pps</code> / <code>attack_min_bps</code> — absolute floors; detection never goes blind on quiet servers.</li><li><code>openshield schedule suppress baseline &lt;duration&gt;</code> — pause learning ahead of a known traffic spike (maintenance, launches).</li></ul>`,21)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
